def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    op = [h[1] for h in history]
    my = [h[0] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_d = my.count('D')

    # Always defect if opponent never cooperates
    if op_c == 0:
        return 'D'

    # Adaptive probing: if opponent has never defected, probe every 10 rounds
    if op_d == 0:
        if n >= 10 and n % 10 == 0:
            return 'D'
        return 'C'

    # If op_d > 0, use forgiving TFT
    last_opp = op[-1]
    last_me = my[-1]

    # Forgive the retaliation to our probe: (D,C) then (C,D)
    if n >= 2:
        h2 = history[-2]
        h1 = history[-1]
        if h2[0] == 'D' and h2[1] == 'C' and h1[0] == 'C' and h1[1] == 'D':
            return 'C'

    # If opponent defected last two rounds, defect
    if len(op) >= 2 and op[-1] == 'D' and op[-2] == 'D':
        return 'D'

    # Standard forgiving TFT
    if last_opp == 'D':
        if last_me == 'D':
            if op_d * 2 > n:
                return 'D'
            return 'C'
        else:
            return 'D'
    else:  # last_opp == 'C'
        if last_me == 'D':
            return 'C'
        return 'C'
